{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "In humans, lycopene—a large, highly lipophilic polyisoprenoid with no ionizable groups—showed only 0.17% systemic availability after oral ingestion, directly demonstrating that this physicochemical class has very poor oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "One lycopene study reported 23.2% ± 8% bioavailability for all-trans lycopene, indicating variability and a possible high-F outcome in some conditions, but this is an outlier among multiple low estimates.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Isradipine and other small-molecule drugs had human oral bioavailability of 32–52%, but their small, drug-like, moderately soluble structures are not representative of the query's extreme lipophilicity and size.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Alprenolol had low oral bioavailability (4.46%) in humans, showing that low F can occur, but its first-pass metabolism mechanism is not transferable to the query's solubility-limited absorption.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a CoQ10-like decaprenyl benzoquinone with extreme lipophilicity, high molecular weight, and no ionizable groups. The closest structural analogue, lycopene, consistently shows very low oral systemic availability in humans, while the high-F small-molecule records are not structurally transferable. Therefore low F (<20%) is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule (ubiquinone/CoQ10-like).",
    "Lycopene is the closest structural analogue but has a low assay-transfer score; carotenoid vs quinone chemistry may alter absorption details.",
    "No data on formulation or fed/fasted effects for the query; CoQ10 bioavailability can be formulation-dependent."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C08"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "lycopene"
    },
    {
      "applicability": "low",
      "card_ids": ["C19"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "small_molecule_drugs"
    },
    {
      "applicability": "low",
      "card_ids": ["C20"],
      "decision_effect": "no_change",
      "direction": "supportive",
      "family": "alprenolol"
    }
  ],
  "revision_action": "initial"
}

